use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [doc = " Abstraction over a message in a subdiagnostic (i.e. label, note, help, etc) to support both"] # [doc = " translatable and non-translatable diagnostic messages."] # [doc = ""] # [doc = " Translatable messages for subdiagnostics are typically attributes attached to a larger Fluent"] # [doc = " message so messages of this type must be combined with a `DiagMessage` (using"] # [doc = " `DiagMessage::with_subdiagnostic_message`) before rendering. However, subdiagnostics from"] # [doc = " the `Subdiagnostic` derive refer to Fluent identifiers directly."] # [rustc_diagnostic_item = "SubdiagMessage"] pub enum SubdiagMessage { # [doc = " Non-translatable diagnostic message."] Str (Cow < 'static , str >) , # [doc = " Translatable message which has already been translated eagerly."] # [doc = ""] # [doc = " Some diagnostics have repeated subdiagnostics where the same interpolated variables would"] # [doc = " be instantiated multiple times with different values. These subdiagnostics' messages"] # [doc = " are translated when they are added to the parent diagnostic, producing this variant of"] # [doc = " `DiagMessage`."] Translated (Cow < 'static , str >) , # [doc = " Identifier of a Fluent message. Instances of this variant are generated by the"] # [doc = " `Subdiagnostic` derive."] FluentIdentifier (FluentId) , # [doc = " Attribute of a Fluent message. Needs to be combined with a Fluent identifier to produce an"] # [doc = " actual translated message. Instances of this variant are generated by the `fluent_messages`"] # [doc = " macro."] # [doc = ""] # [doc = " <https://projectfluent.org/fluent/guide/attributes.html>"] FluentAttr (FluentId) , }